package com.mlserve.inference;

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class ModelInferenceServer {

    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final Map<String, ServiceRegistration> serviceRegistry = new ConcurrentHashMap<>();
    private static final Set<String> ALLOWED_SCHEMES = Set.of("https");
    private static final Set<String> INTERNAL_NETWORKS = Set.of("10.", "172.16.", "172.17.", "172.18.", "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.", "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.", "192.168.");
    private static final byte[] SIGNING_KEY = System.getenv("SERVICE_SIGNING_KEY") != null ? 
        System.getenv("SERVICE_SIGNING_KEY").getBytes(StandardCharsets.UTF_8) : 
        "default-dev-key-change-in-prod".getBytes(StandardCharsets.UTF_8);

    static class ServiceRegistration {
        String serviceId;
        String callbackUrl;
        String publicKey;
        long registeredAt;
        boolean verified;

        ServiceRegistration(String serviceId, String callbackUrl, String publicKey) {
            this.serviceId = serviceId;
            this.callbackUrl = callbackUrl;
            this.publicKey = publicKey;
            this.registeredAt = System.currentTimeMillis();
            this.verified = false;
        }
    }

    public static String computeHmac(String data) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGORITHM);
        SecretKeySpec keySpec = new SecretKeySpec(SIGNING_KEY, HMAC_ALGORITHM);
        mac.init(keySpec);
        byte[] rawHmac = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(rawHmac);
    }

    public static boolean isInternalAddress(String host) {
        for (String prefix : INTERNAL_NETWORKS) {
            if (host.startsWith(prefix)) return true;
        }
        if (host.equals("127.0.0.1") || host.equals("localhost") || host.equals("0.0.0.0")) {
            return true;
        }
        return false;
    }

    public static ValidationResult validateCallbackUrl(String urlString) {
        try {
            URI uri = new URI(urlString);
            String scheme = uri.getScheme();
            if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
                return new ValidationResult(false, "Invalid scheme: must be HTTPS");
            }
            String host = uri.getHost();
            if (host == null || host.isEmpty()) {
                return new ValidationResult(false, "Missing host");
            }
            if (isInternalAddress(host)) {
                return new ValidationResult(false, "Internal addresses not allowed");
            }
            return new ValidationResult(true, "Valid");
        } catch (URISyntaxException e) {
            return new ValidationResult(false, "Malformed URI");
        }
    }

    static class ValidationResult {
        boolean valid;
        String message;
        ValidationResult(boolean valid, String message) {
            this.valid = valid;
            this.message = message;
        }
    }

    public static String registerService(String serviceId, String callbackUrl, String publicKey, String signature) throws Exception {
        String expectedSig = computeHmac(serviceId + ":" + callbackUrl);
        if (!MessageDigest.isEqual(expectedSig.getBytes(), signature.getBytes())) {
            return "{\"error\": \"Invalid signature\"}";
        }
        ValidationResult validation = validateCallbackUrl(callbackUrl);
        if (!validation.valid) {
            return "{\"error\": \"" + validation.message + "\"}";
        }
        ServiceRegistration reg = new ServiceRegistration(serviceId, callbackUrl, publicKey);
        serviceRegistry.put(serviceId, reg);
        return "{\"status\": \"registered\", \"serviceId\": \"" + serviceId + "\"}";
    }

    public static String verifyServiceEndpoint(String serviceId) throws Exception {
        ServiceRegistration reg = serviceRegistry.get(serviceId);
        if (reg == null) {
            return "{\"error\": \"Service not found\"}";
        }
        String verificationToken = computeHmac(serviceId + ":" + reg.registeredAt);
        String verifyUrl = reg.callbackUrl + "/.well-known/ml-verify?token=" + URLEncoder.encode(verificationToken, "UTF-8");
        return performVerificationRequest(verifyUrl, serviceId);
    }

    private static String performVerificationRequest(String targetUrl, String serviceId) throws Exception {
        // Re-validate the final constructed URL before making the request
        URI finalUri = new URI(targetUrl);
        String resolvedHost = finalUri.getHost();

        // DNS resolution check - resolve to IP and verify it's not internal
        InetAddress[] addresses = InetAddress.getAllByName(resolvedHost);
        for (InetAddress addr : addresses) {
            String hostAddress = addr.getHostAddress();
            if (isInternalAddress(hostAddress) || addr.isLoopbackAddress() || addr.isLinkLocalAddress()) {
                return "{\"error\": \"Resolved to internal address\"}";
            }
        }

        URL url = finalUri.toURL();
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(5000);
        conn.setReadTimeout(5000);
        conn.setInstanceFollowRedirects(false);

        int responseCode = conn.getResponseCode();

        if (responseCode >= 300 && responseCode < 400) {
            String redirectLocation = conn.getHeaderField("Location");
            if (redirectLocation != null) {
                return handleRedirect(redirectLocation, serviceId, 0);
            }
        }

        if (responseCode == 200) {
            BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                response.append(line);
            }
            reader.close();
            ServiceRegistration reg = serviceRegistry.get(serviceId);
            if (reg != null) reg.verified = true;
            return "{\"status\": \"verified\", \"response\": \"" + response.toString().replace("\"", "\\\"") + "\"}";
        }

        return "{\"error\": \"Verification failed with status " + responseCode + "\"}";
    }

    private static String handleRedirect(String redirectUrl, String serviceId, int depth) throws Exception {
        if (depth >= 3) {
            return "{\"error\": \"Too many redirects\"}";
        }

        URI redirectUri = new URI(redirectUrl);

        // For relative redirects, we trust them as they stay on the same host
        if (redirectUri.getHost() == null) {
            ServiceRegistration reg = serviceRegistry.get(serviceId);
            if (reg == null) return "{\"error\": \"Service not found\"}";
            URI baseUri = new URI(reg.callbackUrl);
            redirectUri = baseUri.resolve(redirectUri);
        }

        String scheme = redirectUri.getScheme();
        if (scheme != null && !ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
            return "{\"error\": \"Invalid redirect scheme\"}";
        }

        // Validate redirect target host
        String redirectHost = redirectUri.getHost();
        if (redirectHost != null && isInternalAddress(redirectHost)) {
            return "{\"error\": \"Redirect to internal address blocked\"}";
        }

        return performVerificationRequest(redirectUri.toString(), serviceId);
    }

    public static String dispatchInference(String serviceId, String modelPayload) throws Exception {
        ServiceRegistration reg = serviceRegistry.get(serviceId);
        if (reg == null) {
            return "{\"error\": \"Service not found\"}";
        }
        if (!reg.verified) {
            return "{\"error\": \"Service not verified\"}";
        }

        String inferenceUrl = reg.callbackUrl + "/v1/inference";
        URI inferenceUri = new URI(inferenceUrl);

        URL url = inferenceUri.toURL();
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(30000);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setRequestProperty("X-Service-Auth", computeHmac(serviceId + ":inference"));

        try (OutputStream os = conn.getOutputStream()) {
            os.write(modelPayload.getBytes(StandardCharsets.UTF_8));
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder response = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            response.append(line);
        }
        reader.close();

        return response.toString();
    }
}
